def countSubsequenceWords(s, words):
    waiting = [[] for _ in range(26)]
    for w in words.split(","):
        waiting[ord(w[0]) - 97].append((w, 0))
    matched = 0
    for ch in s:
        bucket = waiting[ord(ch) - 97]
        if not bucket:
            continue
        waiting[ord(ch) - 97] = []
        for w, i in bucket:
            i += 1
            if i == len(w):
                matched += 1
            else:
                waiting[ord(w[i]) - 97].append((w, i))
    return matched
